// static
bool StructTraits<::aim_eligibility::mojom::DriveStatus::DataView, ::aim_eligibility::mojom::DriveStatusPtr>::Read(
    ::aim_eligibility::mojom::DriveStatus::DataView input,
    ::aim_eligibility::mojom::DriveStatusPtr* output) {
  bool success = true;
  ::aim_eligibility::mojom::DriveStatusPtr result(::aim_eligibility::mojom::DriveStatus::New());
  
      if (success)
        result->is_drive_supported = input.is_drive_supported();
      if (success)
        result->is_pec_eligible = input.is_pec_eligible();
      if (success)
        result->is_identity_match = input.is_identity_match();
      if (success)
        result->is_incognito = input.is_incognito();
      if (success)
        result->is_feature_flag_enabled = input.is_feature_flag_enabled();
      if (success)
        result->is_force_drive_disclaimer_accepted = input.is_force_drive_disclaimer_accepted();
      if (success)
        result->is_search_content_sharing_enabled = input.is_search_content_sharing_enabled();
      if (success && !input.ReadDisclaimerState(&result->disclaimer_state))
        success = false;
      if (success)
        result->is_disclaimer_flag_enabled = input.is_disclaimer_flag_enabled();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::aim_eligibility::mojom::EligibilityState::DataView, ::aim_eligibility::mojom::EligibilityStatePtr>::Read(
    ::aim_eligibility::mojom::EligibilityState::DataView input,
    ::aim_eligibility::mojom::EligibilityStatePtr* output) {
  bool success = true;
  ::aim_eligibility::mojom::EligibilityStatePtr result(::aim_eligibility::mojom::EligibilityState::New());
  
      if (success)
        result->is_eligible = input.is_eligible();
      if (success)
        result->is_eligible_by_policy = input.is_eligible_by_policy();
      if (success)
        result->is_third_party_eligible_by_policy = input.is_third_party_eligible_by_policy();
      if (success)
        result->is_eligible_by_dse = input.is_eligible_by_dse();
      if (success)
        result->is_aim_eligible_by_server = input.is_aim_eligible_by_server();
      if (success)
        result->is_fusebox_eligible_by_server = input.is_fusebox_eligible_by_server();
      if (success)
        result->is_cobrowse_eligible_by_server = input.is_cobrowse_eligible_by_server();
      if (success)
        result->is_server_eligibility_enabled = input.is_server_eligibility_enabled();
      if (success && !input.ReadEligibilityResponseBase64Encoded(&result->eligibility_response_base64_encoded))
        success = false;
      if (success && !input.ReadEligibilityResponseSource(&result->eligibility_response_source))
        success = false;
      if (success && !input.ReadEligibilityResponseAuthType(&result->eligibility_response_auth_type))
        success = false;
      if (success && !input.ReadDriveStatus(&result->drive_status))
        success = false;
      if (success && !input.ReadLastUpdated(&result->last_updated))
        success = false;
  *output = std::move(result);
  return success;
}

